// 展台详情：来自各 IP 官方小红书笔记（脚本 scripts/fetch-note.mjs 可抓取新笔记的文字与图片）
// key = booths.js 中的 booth.id
// 字段约定：
//   source      笔记来源（title / url / noteId / author / publishedAt）
//   intro       笔记开头的欢迎语
//   notes       笔记里的注意事项（*开头）
//   activities  展台活动 [{ ip?, title, desc?, items?, ordered?, note?, partner?, needBooking?, rewards?[] }]  ip：多 IP 共用展位时按 IP 分组可收起（阅文）
//   stage       舞台活动 [{ title, desc, schedule?: [{ day, guests[] }] }]  guests 带「HH:MM 」前缀时详情页按整点时段分行
//   tasks       展台任务 [{ ip?, title, desc?, items?, ordered?, note?, tags?[], post?, rewards[] }]  items[].fold 见 StepList
//                 items：官方原文里 Step1 / 01 / 任务 1 这类分步内容，每步一项 { no?, title?, desc, tags?, post?, rewards?, note? } 或字符串，
//                        由 StepList 逐行渲染；ordered=false 为无序列表。tags 为要带的小红书话题；post 为自定义发帖文案模板（默认按话题自动生成）
//   rewards     奖励一览（去重后的所有可领物品）[{ name, how, pin?: true, pinId? | pinIds? }]  pinId 对应 pins.js 的 id，详情页点 PIN 标签预览
//   footnote    奖励说明
//   images      原始笔记图片（public/img/booths/<id>/ 下的相对路径）
//   accounts    可选，多 IP 共用展位时各 IP 的小红书官方账号 [{ uid, name }]（booths.js 的 xhs 只放一个主账号）

